function App() {
  // Illustrative solution — real code lives in app/layout.tsx:
  const lines = [
    "import { Inter, Lora } from 'next/font/google';",
    "const body = Inter({ subsets: ['latin'], variable: '--font-body' });",
    "const heading = Lora({ subsets: ['latin'], variable: '--font-heading' });",
    "export default function RootLayout({ children }) {",
    "  return (",
    "    <html className={`${body.variable} ${heading.variable}`}>",
    "      <body>{children}</body>",
    "    </html>",
    "  );",
    "}",
    "/* CSS: h1 { font-family: var(--font-heading); } body { font-family: var(--font-body); } */",
  ];
  return (
    <pre style={{ fontFamily: 'ui-monospace, monospace', padding: 16, fontSize: 12 }}>
      {lines.join('\n')}
    </pre>
  );
}

