function App() {
  // Illustrative fix — next/font self-hosts and matches fallback metrics:
  const lines = [
    "import { Inter } from 'next/font/google';",
    "const inter = Inter({ subsets: ['latin'], display: 'swap' });",
    "// In layout: <html className={inter.className}>",
    "// -> self-hosted, no Google request, size-adjust fallback = no CLS",
  ];
  return (
    <pre style={{ fontFamily: 'ui-monospace, monospace', padding: 16, fontSize: 12 }}>
      {lines.join('\n')}
    </pre>
  );
}

// app/layout.tsx
import { Inter } from 'next/font/google';
import localFont from 'next/font/local';

const inter = Inter({ subsets: ['latin'], display: 'swap' });
const brand = localFont({ src: './fonts/Brand.woff2', variable: '--font-brand' });

export default function RootLayout({ children }: { children: React.ReactNode }) {
  return (
    <html lang="en" className={`${inter.className} ${brand.variable}`}>
      <body>{children}</body>
    </html>
  );
}
// CSS: h1 { font-family: var(--font-brand); }
